<?php
require_once __DIR__.'/config/config.php'; require_once __DIR__.'/config/db.php';
$type=$_GET['type']??'lost';$id=(int)($_GET['id']??0);$table=$type==='found'?'found_items':'lost_items';$datecol=$type==='found'?'found_date':'lost_date';
$s=$pdo->prepare("SELECT i.*,c.name category_name,loc.name location_name,st.name status_name,u.name reporter FROM $table i JOIN categories c ON c.id=i.category_id JOIN locations loc ON loc.id=i.location_id JOIN statuses st ON st.id=i.status_id JOIN users u ON u.id=i.user_id WHERE i.id=?");$s->execute([$id]);$item=$s->fetch();
if(!$item){http_response_code(404);$page_title='Not found';include __DIR__.'/includes/header.php';echo '<div class="glass-panel p-5 text-center"><h2>Item not found</h2></div>';include __DIR__.'/includes/footer.php';exit;}
$page_title=$item['title'];include __DIR__.'/includes/header.php'; ?>
<div class="py-4"><a href="javascript:history.back()" class="btn btn-glass mb-4"><i class="bi bi-arrow-left"></i> Back</a><div class="row g-5"><div class="col-lg-6"><?php if($item['image_path']):?><img src="<?=BASE_URL.'/'.e($item['image_path'])?>" class="w-100 rounded-4" style="max-height:520px;object-fit:cover"><?php else:?><div class="placeholder-thumb rounded-4" style="height:520px"><i class="bi bi-image"></i></div><?php endif;?></div><div class="col-lg-6"><span class="badge rounded-pill badge-soft"><?=e($item['category_name'])?></span><h1 class="section-title mt-3"><?=$item['title']?></h1><p class="text-secondary mt-3"><?=nl2br(e($item['description']))?></p><div class="glass-panel p-4 mt-4"><div class="row g-3"><div class="col-6"><small class="text-secondary">Location</small><strong class="d-block"><?=e($item['location_name'])?></strong></div><div class="col-6"><small class="text-secondary">Date</small><strong class="d-block"><?=date('d M Y',strtotime($item[$datecol]))?></strong></div><div class="col-6"><small class="text-secondary">Status</small><strong class="d-block"><?=e($item['status_name'])?></strong></div><div class="col-6"><small class="text-secondary">Reported by</small><strong class="d-block"><?=e($item['reporter'])?></strong></div></div></div><?php if(is_logged_in()):?><a href="<?=BASE_URL?>/claim.php?type=<?=$type?>&id=<?=$id?>" class="btn btn-primary-glass px-4 py-3 mt-4">Submit ownership claim <i class="bi bi-patch-check"></i></a><?php endif;?></div></div></div>
<?php include __DIR__.'/includes/footer.php'; ?>
